insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '유명인이 나오는 꿈'), '유명인과-대화하는-꿈', '유명인과 대화하는 꿈', '화면 속에서만 보던 유명인과 자연스럽게 대화를 나누는 꿈이다. 이런 꿈은 전통적으로 꿈꾼 사람이 평소 동경하던 삶의 방식이나 성취를 마음속으로 그리고 있다는 의미로 해석되곤 한다. 대화가 편안하고 즐거웠다면, 자신감이 차오르고 있는 상태를 반영한다고 풀이하는 경우가 많다. 대화 내용이 구체적으로 기억난다면 그 말 속에 최근 고민에 대한 힌트가 담겨 있다고 보는 시선도 있다. 반대로 대화가 어색하거나 뜻이 통하지 않았다면, 원하는 목표와 현재 사이에 거리감을 느끼고 있다는 신호로 여겨지기도 한다. 어느 쪽이든 유명인과의 대화는 스스로를 특별하게 바라보고 싶은 마음의 표현으로 받아들이면 무난하다.', '동경하던 목표에 다가서는 자신감', array[3,14,21,28,35,42], 1),
  ((select id from public.dreams where keyword = '유명인이 나오는 꿈'), '유명인과-친해지는-꿈', '유명인과 친해지는 꿈', '처음엔 낯설던 유명인과 점점 가까워져 편한 친구처럼 지내는 꿈이다. 이런 전개는 전통적으로 꿈꾼 사람의 대인관계 운이 서서히 넓어지고 있다는 뜻으로 해석되곤 한다. 서로 농담을 주고받거나 함께 시간을 보내는 장면이 나왔다면, 새로운 인연이나 좋은 기회가 가까이 다가오고 있다는 뜻으로 풀이되기도 한다. 친해지는 과정이 자연스러웠을수록 현실에서도 사람들과의 관계가 순조롭게 풀릴 조짐으로 여겨진다. 다만 급하게 친해지려다 어색한 순간이 있었다면, 관계를 서두르지 말고 천천히 다가가라는 뜻으로 받아들이는 시선도 있다. 전체적으로는 사람과의 인연이 넓어지는 긍정적인 신호로 보는 경우가 많다.', '대인관계가 넓어지는 좋은 신호', array[2,9,17,24,33,41], 2),
  ((select id from public.dreams where keyword = '유명인이 나오는 꿈'), '유명인에게-선물을-받는-꿈', '유명인에게 선물을 받는 꿈', '뜻밖에도 유명인에게서 선물을 건네받는 꿈이다. 예로부터 꿈속에서 무언가를 받는 장면은 실제로 물건을 얻는다는 뜻보다, 뜻하지 않은 좋은 소식이나 기회가 찾아온다는 의미로 해석되는 경우가 많다. 받은 선물이 화려하고 귀해 보였다면 그만큼 기대할 만한 좋은 흐름이 다가오고 있다는 뜻으로 풀이되기도 한다. 선물을 받으며 기분이 좋았는지도 중요한 단서로 여겨지는데, 흔쾌히 받아 들었다면 다가올 기회를 스스로도 반기고 있다는 신호로 본다. 포장을 풀어보는 장면까지 이어졌다면, 그 기회의 실체가 곧 구체적으로 드러날 것이라는 해석도 있다. 이처럼 유명인에게 선물을 받는 꿈은 대체로 반가운 변화를 예고하는 꿈으로 여겨진다.', '뜻밖의 좋은 소식이 찾아오는 신호', array[5,12,19,26,34,45], 3),
  ((select id from public.dreams where keyword = '유명인이 나오는 꿈'), '유명인과-사진을-찍는-꿈', '유명인과 사진을 찍는 꿈', '유명인과 나란히 서서 사진을 찍는 꿈이다. 사진이라는 소재는 전통적으로 어떤 순간이나 관계를 오래 남기고 싶어 하는 마음을 상징한다고 해석되곤 한다. 유명인과 함께 찍은 사진이 잘 나왔다면, 지금의 노력이나 성과가 주변에 좋은 인상으로 남을 것이라는 뜻으로 풀이되기도 한다. 사진을 찍는 순간이 즐겁고 자연스러웠는지, 아니면 어딘가 불편했는지에 따라 해석의 결이 달라질 수 있다. 마음이 편안했다면 자신의 성취를 있는 그대로 인정받고 싶어 하는 심리로 보는 시선이 많고, 다소 긴장했다면 남에게 보여지는 모습에 신경 쓰고 있다는 뜻으로 여겨지기도 한다. 전체적으로는 자신을 드러내고 인정받고 싶은 마음이 반영된 꿈으로 받아들이면 좋다.', '인정받고 싶은 마음이 드러난 꿈', array[4,11,20,27,36,43], 4),
  ((select id from public.dreams where keyword = '유명인이 나오는 꿈'), '낯선-유명인을-보는-꿈', '낯선 유명인을 보는 꿈', '누구인지 정확히 알 수 없는 유명인이 멀리서 스쳐 지나가는 꿈이다. 이렇게 잘 알지 못하는 인물이 꿈에 등장하면 특정한 사람보다는 아직 마음속에서 뚜렷하게 정리되지 않은 바람이나 목표를 나타낸다고 보는 시선이 많다. 가까이 다가가지 못하고 지켜보기만 했다면, 원하는 무언가에 아직 다가서지 못하고 있다는 뜻으로 풀이되기도 한다. 그 사람이 누구인지 궁금해하며 애를 썼던 기억이 남는다면, 스스로도 뚜렷하게 알지 못하는 목표를 찾아가는 과정에 있다는 의미로 해석되곤 한다. 굳이 정체를 알아내지 못했다고 해서 나쁜 조짐으로 볼 필요는 없으며, 아직 구체화되지 않은 가능성 정도로 담담하게 받아들이는 편이 좋겠다. 뚜렷한 사건 없이 스쳐 지나가는 만남이었던 만큼, 큰 의미를 부여하기보다는 마음의 여운 정도로 넘기는 것이 무난하다.', '아직 정리되지 않은 막연한 기대감', null, 5)
on conflict (dream_id, keyword) do nothing;

-- C-10. 친구가 나오는 꿈 (신규 Parent, category: 인물)
with new_dream_10 as (
  insert into public.dreams (keyword, category, interpretation)
  select '친구가 나오는 꿈', '인물', '## 친구가 나오는 꿈은 보통 어떻게 해석할까?
꿈에 등장하는 친구는 현실의 우정 그 자체를 의미하기도 하지만, 전통적인 해몽에서는 나와 가장 가까운 관계에서 오가는 감정이나 소통 방식을 비추는 거울로 보는 경우가 많다. 친구와 다투거나 화해하는 장면, 함께 웃고 우는 장면들은 실제 그 친구와의 관계보다 꿈꾼 사람 스스로의 마음 상태를 드러낸다고 해석되곤 한다. 오랜만에 만나는 친구는 지나간 시절에 대한 그리움이나 놓치고 있던 감정을 떠올리게 하는 매개체로 여겨지기도 한다. 이처럼 친구 꿈은 인간관계 전반에 대한 심리를 담고 있다고 보는 시선이 일반적이다.

## 감정의 결에 따라 달라지는 해석
같은 친구가 나오는 꿈이라도 다투는 꿈인지, 우는 꿈인지, 함께 여행을 떠나는 꿈인지에 따라 담긴 뜻이 사뭇 다르다고 본다. 갈등이 담긴 꿈은 억눌러온 감정이 드러나는 것으로, 화기애애한 꿈은 관계에 대한 만족감이나 기대감으로 풀이되는 경우가 많다.

## 숫자 매핑에 대한 안내
아래 숫자는 친구라는 소재가 지닌 친밀함과 신뢰의 이미지를 바탕으로 구성한 것이며, 결과를 보장하기보다는 참고 삼아 가볍게 즐기는 용도로 활용하면 좋다.'
  where not exists (select 1 from public.dreams where keyword = '친구가 나오는 꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[3,11,19,27,34,42] from new_dream_10;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '친구가 나오는 꿈'), '친구와-싸우는-꿈', '친구와 싸우는 꿈', '평소 가깝게 지내던 친구와 언성을 높이며 다투는 꿈이다. 이런 꿈은 실제로 그 친구와 사이가 나빠진다는 뜻으로 보기보다, 마음속에 쌓여 있던 서운함이나 스트레스가 꿈을 통해 표출된 것이라는 해석이 많다. 다투는 이유가 사소했다면 별다른 의미 없이 일상의 자잘한 감정이 정리되는 과정으로 여겨지기도 한다. 반대로 심각한 이유로 다퉜다면, 관계에서 그동안 말하지 못했던 속마음이 있다는 신호로 보는 시선도 있다. 다툰 뒤 화해까지 이어졌다면 오히려 관계가 한층 더 단단해질 조짐으로 풀이되기도 한다. 친구와 싸우는 꿈을 꿨다고 해서 불안해하기보다는, 마음을 한 번 들여다보라는 신호 정도로 담담하게 받아들이면 좋겠다.', '쌓여 있던 감정이 드러나는 신호', null, 1),
  ((select id from public.dreams where keyword = '친구가 나오는 꿈'), '오랜만에-친구를-만나는-꿈', '오랜만에 친구를 만나는 꿈', '한동안 소식이 끊겼던 친구를 우연히 마주치는 꿈이다. 오래도록 만나지 못했던 인연이 꿈에 등장하면, 전통적으로 그 시절의 감정이나 지금은 잊고 지내던 마음이 다시 떠오른 것이라는 해석이 많다. 반갑게 인사를 나누고 이야기꽃을 피웠다면, 잃어버렸던 활력이나 좋은 인연이 다시 이어질 조짐으로 풀이되기도 한다. 서로를 알아보지 못하거나 서먹했다면, 그때의 감정을 아직 완전히 정리하지 못했다는 뜻으로 여겨지는 시선도 있다. 대화 내용이 즐거웠을수록 현재의 인간관계에도 좋은 기운이 스며든다는 해석이 흔하다. 오랜만에 친구를 만나는 꿈은 대체로 반가운 인연과 활기를 예고하는 꿈으로 여겨진다.', '잊고 지낸 좋은 인연이 되살아남', array[6,13,22,30,38,44], 2),
  ((select id from public.dreams where keyword = '친구가 나오는 꿈'), '친구가-우는-꿈', '친구가 우는 꿈', '친한 친구가 눈물을 흘리며 힘들어하는 모습을 지켜보는 꿈이다. 이런 꿈은 실제로 그 친구에게 안 좋은 일이 생긴다는 뜻으로 단정하기보다는, 꿈꾼 사람이 평소 그 친구를 얼마나 신경 쓰고 있는지를 보여주는 장면으로 해석되는 경우가 많다. 친구를 위로해주는 데까지 이어졌다면, 관계 안에서 서로를 챙기는 마음이 잘 자리 잡고 있다는 뜻으로 풀이되기도 한다. 우는 이유가 뚜렷하게 기억나지 않는다면, 걱정거리 자체보다는 막연한 안타까움이 마음에 남아 있는 상태로 보는 시선도 있다. 꿈에서 느낀 감정이 슬픔이었는지 안쓰러움이었는지에 따라서도 해석은 조금씩 달라질 수 있다. 지나치게 불안해하기보다는 가까운 사람에게 마음을 쓰고 있다는 신호 정도로 편안하게 받아들이는 편이 좋겠다.', '가까운 사람을 향한 마음 씀씀이', null, 3),
  ((select id from public.dreams where keyword = '친구가 나오는 꿈'), '친구를-잃어버리는-꿈', '친구를 잃어버리는 꿈', '함께 있던 친구가 어느 순간 보이지 않아 이곳저곳을 찾아 헤매는 꿈이다. 꿈속에서 누군가를 잃어버리는 장면은 전통적으로 관계에 대한 불안감이나 소통이 부족하다고 느끼는 마음을 반영한다고 해석되곤 한다. 찾아 헤매다가 결국 다시 만났다면, 걱정과 달리 관계는 여전히 든든하게 이어지고 있다는 뜻으로 풀이되기도 한다. 끝내 찾지 못한 채 꿈에서 깼다면, 요즘 그 친구와 거리감을 느끼고 있지는 않은지 스스로 돌아보라는 신호로 보는 시선도 있다. 찾는 과정에서 느낀 조급함이 컸을수록 관계를 소중히 여기는 마음이 크다는 뜻으로 해석되기도 한다. 친구를 잃어버리는 꿈은 사이가 실제로 멀어진다는 의미보다는, 관계에 조금 더 마음을 써보라는 담담한 신호로 받아들이면 무난하다.', '관계에 마음을 써보라는 신호', null, 4),
  ((select id from public.dreams where keyword = '친구가 나오는 꿈'), '친구와-여행을-가는-꿈', '친구와 여행을 가는 꿈', '친구와 함께 짐을 꾸려 어딘가로 여행을 떠나는 꿈이다. 여행이라는 소재는 예로부터 새로운 국면이나 변화를 상징한다고 해석되는 경우가 많고, 친구와 동행했다면 그 변화를 믿을 만한 사람과 함께 헤쳐 나가고 싶어 하는 마음으로 풀이되기도 한다. 여행 중 즐거운 순간이 많았다면, 관계에서 오는 안정감과 든든함이 최근의 활력으로 이어지고 있다는 뜻으로 여겨진다. 목적지에 무사히 도착하는 장면까지 이어졌다면, 함께 계획한 일이 순조롭게 풀릴 조짐으로 보는 시선도 있다. 여행길에 예상치 못한 일이 생겼더라도 친구와 함께였다면 큰 걱정 없이 헤쳐 나갈 힘이 있다는 의미로 해석되기도 한다. 전체적으로 친구와 여행을 가는 꿈은 관계에서 오는 든든함과 새로운 활력을 상징하는 꿈으로 여겨진다.', '함께라서 든든한 새로운 활력', array[8,16,25,31,39,45], 5)
on conflict (dream_id, keyword) do nothing;

-- C-11. 부모님이 나오는 꿈 (신규 Parent, category: 인물)
with new_dream_11 as (
  insert into public.dreams (keyword, category, interpretation)
  select '부모님이 나오는 꿈', '인물', '## 부모님이 나오는 꿈은 보통 어떻게 해석할까?
부모님은 꿈에서 가장 자주, 그리고 가장 다양한 감정으로 등장하는 인물 중 하나다. 전통적인 해몽에서는 부모님을 안정감과 뿌리, 든든한 울타리를 상징하는 존재로 보는 경우가 많아, 부모님이 나오는 꿈은 그 자체로 현재 자신이 느끼는 안정감이나 불안감을 비추는 거울로 해석되곤 한다. 부모님이 웃는 꿈처럼 편안한 장면은 마음의 여유로, 걱정스러운 장면은 최근 느끼는 부담감으로 풀이되는 경우가 흔하다. 다만 이런 꿈들은 실제 부모님의 건강이나 안위를 예고한다기보다, 꿈꾼 사람 내면의 심리 상태를 담고 있다고 보는 시선이 일반적이다.

## 걱정스러운 장면을 대하는 태도
부모님이 편찮으시거나 길을 잃는 꿈처럼 불안한 내용이 담긴 경우에도, 이는 실제 사건을 예고한다기보다 평소 부모님을 향한 애틋한 마음이나 스스로 느끼는 책임감이 꿈으로 드러난 것으로 여겨지는 경우가 많다. 지나치게 걱정하기보다는 마음을 살펴보는 계기로 삼는 편이 좋다.

## 숫자 매핑에 대한 안내
아래 숫자는 부모님이라는 소재가 주는 안정감과 뿌리의 이미지를 참고해 구성한 것으로, 결과를 단정하기보다는 편안하게 참고하는 용도로 활용하면 좋겠다.'
  where not exists (select 1 from public.dreams where keyword = '부모님이 나오는 꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[2,9,16,24,31,38] from new_dream_11;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '부모님이 나오는 꿈'), '부모님이-웃는-꿈', '부모님이 웃는 꿈', '부모님이 환하게 웃는 얼굴로 곁에 계시는 꿈이다. 이런 꿈은 전통적으로 집안에 평안한 기운이 감돌고 있다는 뜻으로 해석되곤 하며, 꿈꾼 사람 스스로도 마음의 여유를 되찾고 있다는 신호로 풀이되기도 한다. 부모님과 함께 이야기를 나누며 웃었다면, 가족 간의 소통이 원활하게 이루어지고 있다는 뜻으로 여겨지는 경우가 많다. 웃는 모습이 유난히 젊고 생기 있어 보였다면, 집안 전체에 좋은 기운이 스며들고 있다는 해석도 있다. 꿈에서 느낀 편안함이 클수록 현실에서도 안정된 나날이 이어질 조짐으로 보는 시선이 흔하다. 부모님이 웃는 꿈은 걱정 없이 그대로 반가운 마음으로 받아들여도 좋은 꿈으로 여겨진다.', '집안에 감도는 평안하고 좋은 기운', array[4,10,18,26,33,40], 1),
  ((select id from public.dreams where keyword = '부모님이 나오는 꿈'), '부모님이-편찮으신-꿈', '부모님이 편찮으신 꿈', '부모님이 몸이 편찮으셔서 자리에 누워 계신 모습을 보는 꿈이다. 이런 꿈을 꾸면 마음이 철렁 내려앉기 마련이지만, 전통적인 해몽에서는 실제 건강 문제를 예고한다기보다 평소 부모님을 향해 품고 있는 걱정과 책임감이 꿈으로 드러난 것이라는 해석이 많다. 곁에서 간호하거나 돌보는 장면이 이어졌다면, 가족에 대한 애정과 살뜰한 마음이 크다는 뜻으로 풀이되기도 한다. 걱정스러운 마음에 잠에서 깼더라도, 이는 심리적인 불안이 반영된 것일 뿐 실제 사건과 직접 연결 짓지 않는 편이 좋다는 시선이 일반적이다. 꿈속에서 부모님이 다시 기운을 차리는 모습으로 이어졌다면, 마음속 걱정도 곧 가라앉을 것이라는 뜻으로 여겨지기도 한다. 이런 꿈을 꾸었다면 안부 전화를 한 통 드리는 정도로 마음을 편안하게 다스리는 것이 좋겠다.', '가족을 향한 애틋한 걱정과 책임감', null, 2),
  ((select id from public.dreams where keyword = '부모님이 나오는 꿈'), '부모님과-여행하는-꿈', '부모님과 여행하는 꿈', '부모님과 나란히 짐을 꾸려 여행을 떠나는 꿈이다. 가족과 함께하는 여행은 예로부터 화목함과 정서적인 안정을 상징한다고 해석되는 경우가 많고, 부모님과 동행했다면 그 의미가 한층 더 크게 다가온다고 보는 시선도 있다. 여행 내내 즐거운 시간을 보냈다면, 가족 관계에서 오는 든든함이 최근의 마음가짐에도 좋은 영향을 주고 있다는 뜻으로 풀이되기도 한다. 낯선 풍경을 함께 구경하거나 맛있는 음식을 나눠 먹는 장면이 기억난다면, 소소한 행복이 이어질 조짐으로 여겨지기도 한다. 여행 중 사소한 어려움이 있었더라도 부모님과 함께였다면 큰 걱정 없이 넘어갈 수 있다는 의미로 해석되는 경우가 많다. 전체적으로 부모님과 여행하는 꿈은 가족의 화목함과 정서적 안정을 상징하는 꿈으로 여겨진다.', '가족의 화목함과 정서적 안정', array[7,15,23,29,36,43], 3),
  ((select id from public.dreams where keyword = '부모님이 나오는 꿈'), '부모님께-혼나는-꿈', '부모님께 혼나는 꿈', '어린 시절로 돌아간 듯 부모님께 꾸중을 듣는 꿈이다. 이런 꿈은 전통적으로 실제 잘못을 저질렀다는 뜻보다는, 스스로 어떤 일에 대해 마음 한켠에 자책하는 부분이 있다는 신호로 해석되는 경우가 많다. 혼이 나면서도 마음이 무겁지 않았다면, 오히려 그 지적을 통해 스스로를 다잡고 있다는 뜻으로 풀이되기도 한다. 꾸중의 내용이 구체적으로 기억난다면, 최근 신경 쓰고 있는 일과 맞닿아 있을 가능성이 있다고 보는 시선도 있다. 혼난 뒤 부모님이 다독여 주는 장면으로 이어졌다면, 걱정하던 일이 무난하게 마무리될 조짐으로 여겨지기도 한다. 부모님께 혼나는 꿈은 불안해하기보다는 스스로를 돌아보는 계기로 가볍게 받아들이면 좋겠다.', '스스로를 돌아보게 하는 신호', null, 4),
  ((select id from public.dreams where keyword = '부모님이 나오는 꿈'), '부모님을-잃어버리는-꿈', '부모님을 잃어버리는 꿈', '함께 있던 부모님이 인파 속에서 갑자기 사라져 애타게 찾아다니는 꿈이다. 이렇게 가까운 가족을 잃어버리는 꿈은 전통적으로 그 사람에 대한 애착과 함께, 홀로 서야 한다는 부담감이 뒤섞여 나타난 것으로 해석되는 경우가 많다. 결국 다시 만나는 장면으로 마무리되었다면, 걱정과 달리 관계나 상황은 여전히 안정적으로 이어지고 있다는 뜻으로 풀이되기도 한다. 끝내 찾지 못한 채 꿈에서 깼더라도, 이는 실제 이별을 예고한다기보다 막연한 불안감이 표출된 것으로 보는 시선이 일반적이다. 찾는 동안 느낀 절박함이 컸을수록 평소 부모님을 얼마나 의지하고 있는지를 보여주는 것으로 해석되기도 한다. 이런 꿈을 꾸었다면 지나치게 불안해하지 말고, 가족에게 마음을 표현하는 계기로 담담하게 받아들이는 편이 좋겠다.', '가족을 향한 깊은 애착과 부담감', null, 5)
on conflict (dream_id, keyword) do nothing;

-- C-12. 지진이 나는 꿈 (신규 Parent, category: 자연)
with new_dream_12 as (
  insert into public.dreams (keyword, category, interpretation)
  select '지진이 나는 꿈', '자연', '## 지진이 나는 꿈은 보통 어떻게 해석할까?
땅이 흔들리는 지진은 우리가 당연하게 여기던 안정된 기반이 흔들리는 경험이다. 전통적인 해몽에서는 지진을 현실에서 느끼는 변화나 불안정한 상황, 혹은 큰 변화를 앞둔 시기를 상징하는 꿈으로 해석하는 경우가 많다. 흔들림의 세기나 그 상황에서 어떻게 대처했는지에 따라 풀이가 달라지는데, 무사히 상황을 벗어났다면 변화를 잘 극복해낼 힘이 있다는 뜻으로 여겨지기도 한다. 반대로 건물이 무너지거나 땅이 갈라지는 장면은 지금까지의 방식이 크게 바뀌는 전환점을 의미한다고 보는 시선도 있다.

## 자연재해 꿈을 대하는 태도
지진처럼 놀라운 자연재해가 등장하는 꿈은 실제 재난을 예고하는 것으로 받아들이기보다, 심리적으로 겪고 있는 변화나 불안정한 마음 상태를 상징적으로 보여주는 것으로 해석하는 편이 일반적이다. 꿈에서 느낀 감정과 그 이후의 전개를 함께 살펴보는 것이 좋다.

## 숫자 매핑에 대한 안내
아래 숫자는 지진이라는 소재가 지닌 변화와 전환의 이미지를 참고해 구성한 것이며, 결과를 단정하기보다는 가볍게 참고하는 용도로 활용하면 좋겠다.'
  where not exists (select 1 from public.dreams where keyword = '지진이 나는 꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[3,12,20,28,35,43] from new_dream_12;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '지진이 나는 꿈'), '지진으로-건물이-흔들리는-꿈', '지진으로 건물이 흔들리는 꿈', '서 있던 건물이 지진으로 크게 흔들리는 꿈이다. 이런 꿈은 전통적으로 지금 처한 상황이나 익숙했던 환경에 변화의 조짐이 나타나고 있다는 뜻으로 해석되곤 한다. 흔들림이 크고 오래갔다면 그만큼 변화의 폭이 크게 느껴진다는 뜻으로 풀이되기도 하고, 금세 잠잠해졌다면 걱정만큼 큰일은 아닐 것이라는 뜻으로 여겨지는 시선도 있다. 흔들리는 동안 침착하게 대처했다면, 다가올 변화에도 흔들리지 않을 마음의 준비가 되어 있다는 의미로 해석되는 경우가 많다. 반대로 당황하며 우왕좌왕했다면, 예상치 못한 변화에 아직 대비가 부족하다고 느끼는 심리로 보기도 한다. 지진으로 건물이 흔들리는 꿈은 변화 자체를 나쁘게 보기보다는, 다가올 변화에 마음을 준비하라는 신호로 받아들이면 좋겠다.', '다가올 변화에 마음을 준비하라는 신호', null, 1),
  ((select id from public.dreams where keyword = '지진이 나는 꿈'), '지진을-피해-대피하는-꿈', '지진을 피해 대피하는 꿈', '지진이 나자마자 서둘러 안전한 곳으로 대피하는 꿈이다. 예로부터 위험을 피해 움직이는 꿈은 실제로 문제를 미리 알아채고 현명하게 대처하는 능력을 상징한다고 해석되는 경우가 많다. 대피 과정이 순조로웠다면, 앞으로 맞이할 변화나 어려움에도 스스로 잘 대응할 수 있다는 뜻으로 풀이되기도 한다. 함께 대피한 사람들이 있었다면, 어려운 시기에도 주변 사람들과 힘을 모을 수 있다는 신호로 보는 시선도 있다. 대피하는 동안 느낀 긴박함이 컸더라도 결국 안전한 곳에 도착했다면, 지금의 걱정도 무사히 지나갈 조짐으로 여겨진다. 지진을 피해 대피하는 꿈은 위기에 대한 대응력을 보여주는 꿈으로, 크게 걱정하지 않아도 좋다는 해석이 많다.', '위기를 알아채는 현명한 대응력', array[1,9,17,26,33,41], 2),
  ((select id from public.dreams where keyword = '지진이 나는 꿈'), '땅이-갈라지는-꿈', '땅이 갈라지는 꿈', '발밑의 땅이 쩍쩍 소리를 내며 갈라지는 꿈이다. 이런 꿈은 전통적으로 지금까지 당연하게 여겨온 기반이나 관계, 상황에 큰 변화가 찾아온다는 뜻으로 해석되곤 한다. 갈라진 틈이 넓고 깊었다면 그만큼 변화의 폭이 크게 느껴진다는 의미로 풀이되는 경우가 많고, 갈라진 틈 사이로 떨어지지 않고 무사히 건너갔다면 위기를 슬기롭게 넘길 힘이 있다는 뜻으로 보는 시선도 있다. 갈라지는 땅을 그저 지켜보기만 했다면, 변화의 흐름을 아직 실감하지 못하고 있는 상태로 해석되기도 한다. 땅이 갈라지는 장면이 무섭게 느껴졌더라도, 이는 두려움 자체보다 새로운 국면에 대한 긴장감이 반영된 것으로 여겨진다. 전체적으로 땅이 갈라지는 꿈은 큰 전환점을 앞두고 있다는 신호로 받아들이면 좋겠다.', '큰 전환점을 앞두고 있다는 신호', null, 3),
  ((select id from public.dreams where keyword = '지진이 나는 꿈'), '지진-속에서-무사한-꿈', '지진 속에서 무사한 꿈', '강한 지진이 일어났음에도 다치지 않고 무사히 상황을 벗어나는 꿈이다. 이런 결말은 전통적으로 큰 어려움이 닥치더라도 결국 잘 헤쳐 나갈 힘이 있다는 뜻으로 해석되는 경우가 많다. 주변 사람들도 함께 무사했다면, 어려운 시기를 곁의 사람들과 함께 이겨낼 수 있다는 신호로 풀이되기도 한다. 무사히 상황이 마무리된 후 안도감을 크게 느꼈다면, 최근 마음속 걱정거리도 곧 해소될 조짐으로 여겨진다. 지진이라는 큰 사건 속에서도 침착함을 잃지 않았다면, 어떤 변화 앞에서도 흔들리지 않는 단단한 마음가짐을 지니고 있다는 뜻으로 해석되는 시선도 있다. 지진 속에서 무사한 꿈은 걱정보다는 안심할 만한 결과를 예고하는 꿈으로 받아들여도 좋다.', '어려움을 헤쳐 나갈 든든한 힘', array[5,14,22,30,37,44], 4),
  ((select id from public.dreams where keyword = '지진이 나는 꿈'), '지진으로-집이-무너지는-꿈', '지진으로 집이 무너지는 꿈', '살고 있던 집이 지진으로 무너져 내리는 꿈이다. 집은 예로부터 삶의 기반이나 안정감을 상징하는 공간으로 여겨지는 만큼, 이런 꿈은 실제로 집에 문제가 생긴다는 뜻보다 지금까지의 익숙한 방식이나 생활에 큰 변화가 다가오고 있다는 신호로 해석되는 경우가 많다. 무너지는 집을 보며 크게 놀랐더라도, 이는 변화 앞에서 느끼는 자연스러운 불안감이 반영된 것으로 보는 시선이 일반적이다. 무너진 자리에서 다시 새롭게 짓는 장면으로 이어졌다면, 혼란스러운 시기가 지나면 새로운 국면이 시작될 조짐으로 풀이되기도 한다. 집을 잃었다는 상실감보다 그 이후에 어떤 감정이 남았는지가 해석에서 더 중요하게 여겨진다. 지진으로 집이 무너지는 꿈을 꾸었다면 불안해하기보다는, 변화의 시기를 담담하게 받아들이는 계기로 삼으면 좋겠다.', '익숙한 방식이 크게 바뀌는 전환점', null, 5)
on conflict (dream_id, keyword) do nothing;

-- C-13. 지갑꿈 (신규 Parent, category: 사물)
with new_dream_13 as (
  insert into public.dreams (keyword, category, interpretation)
  select '지갑꿈', '사물', '## 지갑꿈은 보통 어떻게 해석할까?
지갑은 개인이 지니고 다니는 재물과 신분을 상징하는 물건으로, 꿈속에서 지갑과 관련된 사건은 흔히 재물운이나 자기 관리 상태를 비추는 거울처럼 여겨지곤 한다. 지갑을 잃어버리거나 도둑맞는 꿈은 가지고 있던 기회나 안정감이 흔들리는 상황으로, 지갑을 줍거나 돈이 가득 채워진 지갑을 보는 꿈은 뜻밖의 행운이나 재물의 증가로 풀이되는 경우가 많다.

## 상황별로 조금씩 달라지는 해석
같은 지갑꿈이라도 지갑을 잃는지 얻는지, 그 안에 무엇이 들어 있는지에 따라 해석의 결이 크게 달라진다고 전해진다. 잃어버리거나 빼앗기는 꿈은 대체로 주의와 점검이 필요한 시기를 알리는 신호로, 줍거나 채워지는 꿈은 새로운 기회나 안정이 다가오는 조짐으로 구분해 보는 경우가 많다.

## 지갑꿈을 대할 때 참고할 점
지갑꿈은 결과 하나로 길흉을 단정 짓기보다 꿈속 감정과 상황의 흐름을 함께 살펴보는 것이 좋다고 이야기되곤 한다. 지갑을 잃었더라도 되찾는 과정이 있었는지, 새로 얻었다면 그것을 어떻게 다뤘는지에 따라 세부적인 의미가 달라질 수 있다.'
  where not exists (select 1 from public.dreams where keyword = '지갑꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[5,13,21,27,34,42] from new_dream_13;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '지갑꿈'), '지갑을-잃어버리는-꿈', '지갑을 잃어버리는 꿈', '길을 가다가 지갑이 없어진 것을 알아차리고 당황해하는 꿈이다. 지니고 있던 것을 갑자기 잃어버리는 상황은 전통적으로 가지고 있던 기회나 자신감이 잠시 흔들리는 조짐으로 해석되곤 한다. 지갑을 찾으려고 이곳저곳을 뒤지며 애를 태웠다면 놓치고 있던 부분을 다시 점검해봐야 하는 시기로 풀이되는 경우가 많고, 끝내 찾지 못하고 포기했다면 마음을 정리하고 새로운 국면을 준비하라는 뜻으로 여겨지기도 한다. 꿈에서 느낀 불안감이 클수록 실제 생활에서도 소지품이나 중요한 서류를 한 번 더 챙기게 되는 계기로 삼는 경우가 있다. 이 꿈을 꾼 뒤에는 급하게 결정을 내리기보다 차분히 상황을 되짚어보는 것이 도움이 된다고 이야기되곤 한다.', '지니고 있던 기회나 자신감이 흔들리는 신호', null, 1),
  ((select id from public.dreams where keyword = '지갑꿈'), '지갑을-줍는-꿈', '지갑을 줍는 꿈', '길바닥이나 낯선 장소에서 누군가 흘린 지갑을 발견하고 집어 드는 꿈이다. 뜻하지 않게 무언가를 손에 넣게 되는 장면은 전통적으로 예상치 못한 좋은 소식이나 작은 행운이 따라붙는 신호로 해석되곤 한다. 주운 지갑 안에 신분증이나 연락처가 들어 있어 주인을 찾아주는 꿈이었다면 베푼 만큼 돌아오는 복으로 풀이되는 경우가 많고, 주인을 찾지 못해 지갑을 그대로 가지게 되었다면 뜻밖의 이득이 자신에게 머무를 조짐으로 여겨지기도 한다. 지갑을 여는 순간 느꼈던 설렘이나 기대감은 실제로도 새로운 기회에 마음이 열려 있는 상태를 반영한다고 이야기되곤 한다. 이런 꿈을 꾼 뒤에는 평소 무심코 지나쳤던 제안이나 정보를 다시 살펴보는 계기로 삼는 경우도 있다.', '예상치 못한 작은 행운이 따라붙는 조짐', array[3,11,19,24,32,41], 2),
  ((select id from public.dreams where keyword = '지갑꿈'), '지갑에-돈이-가득한-꿈', '지갑에 돈이 가득한 꿈', '지갑을 열어보니 생각보다 훨씬 많은 돈이 빼곡히 들어 있어 놀라는 꿈이다. 넉넉하게 채워진 지갑은 전통적으로 재물운이나 마음의 여유가 채워지는 상징으로 해석되곤 한다. 지폐가 가지런히 정리되어 있는 모습을 봤다면 그동안 쌓아온 노력이 안정적으로 결실을 맺어가는 흐름으로 풀이되는 경우가 많고, 돈이 넘칠 듯 뒤섞여 있었다면 여러 곳에서 동시에 좋은 소식이 들려올 조짐으로 여겨지기도 한다. 지갑 속 돈을 세어보려 했지만 다 세지 못했다는 꿈이라면 아직 드러나지 않은 가능성이 더 남아 있다는 뜻으로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 실제로 재정 계획을 점검해보는 계기로 삼는 경우가 많다고 전해진다.', '재물운과 마음의 여유가 채워지는 상징', array[7,14,22,28,35,44], 3),
  ((select id from public.dreams where keyword = '지갑꿈'), '지갑을-도둑맞는-꿈', '지갑을 도둑맞는 꿈', '사람이 많은 곳에서 누군가 슬쩍 지갑을 훔쳐 가는 것을 뒤늦게 알아차리는 꿈이다. 자신도 모르는 사이에 소중한 것을 빼앗기는 상황은 전통적으로 주변 사람과의 관계나 재물 관리에 좀 더 주의를 기울여야 한다는 신호로 해석되곤 한다. 범인을 곧바로 붙잡아 지갑을 되찾았다면 위기를 넘기고 상황을 다시 통제하게 되는 조짐으로 풀이되는 경우가 많고, 끝내 도둑을 놓쳐버렸다면 당분간 마음을 졸이며 신경 써야 할 일이 남아 있다는 뜻으로 여겨지기도 한다. 꿈속에서 느낀 억울함이나 분노가 컸다면 현실에서도 손해를 보지 않으려는 마음이 강하게 작용하고 있는 상태로 보기도 한다. 이런 꿈을 꾼 뒤에는 금전 거래나 중요한 약속을 한 번 더 확인해보는 것이 좋다고 이야기되곤 한다.', '재물 관리에 더 주의를 기울여야 할 신호', null, 4),
  ((select id from public.dreams where keyword = '지갑꿈'), '새-지갑을-사는-꿈', '새 지갑을 사는 꿈', '매장을 둘러보다 마음에 드는 새 지갑을 골라 구매하는 꿈이다. 낡은 것을 새것으로 바꾸는 장면은 전통적으로 재물을 담는 그릇 자체가 새로워지거나 씀씀이의 흐름이 바뀌는 신호로 해석되곤 한다. 화려하고 값비싼 지갑을 골랐다면 앞으로의 씀씀이나 벌이가 한층 커질 조짐으로 풀이되는 경우가 많고, 소박하고 단단해 보이는 지갑을 골랐다면 꾸준하고 안정적인 재물 흐름을 바라는 마음이 반영된 것으로 여겨지기도 한다. 지갑을 산 뒤 곧바로 돈을 옮겨 담는 꿈이었다면 묵은 흐름을 정리하고 새로운 계획을 시작하려는 의지로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 실제로 지출 습관이나 재테크 계획을 새롭게 다잡아보는 계기로 삼는 경우도 있다.', '씀씀이와 재물의 흐름이 새로워지는 조짐', array[2,9,17,26,33,40], 5)
on conflict (dream_id, keyword) do nothing;

-- C-14. 반지꿈 (신규 Parent, category: 사물)
with new_dream_14 as (
  insert into public.dreams (keyword, category, interpretation)
  select '반지꿈', '사물', '## 반지꿈은 보통 어떻게 해석할까?
반지는 관계와 약속, 그리고 재물을 함께 상징하는 물건으로 꿈속에서도 인연이나 계약, 소유의 문제와 자주 연결되어 해석되곤 한다. 반지를 받거나 줍는 꿈은 새로운 인연이나 뜻밖의 행운이 찾아오는 신호로, 반지를 잃어버리거나 부러뜨리는 꿈은 관계나 계획에 신경 써야 할 부분이 생기는 조짐으로 풀이되는 경우가 많다.

## 반지의 상태와 상황이 만드는 차이
반지를 얻는지 잃는지, 온전한 상태인지 손상된 상태인지에 따라 해석의 방향이 나뉜다고 전해진다. 반지를 끼는 꿈처럼 스스로 선택하고 받아들이는 상황은 마음가짐이나 역할의 변화를 보여주는 것으로 풀이되는 경우가 많다.

## 반지꿈을 대할 때 참고할 점
반지꿈은 관계에 대한 불안이나 기대가 함께 투영되는 경우가 많아, 꿈속 감정을 찬찬히 되짚어보는 것이 도움이 된다고 이야기되곤 한다. 좋은 조짐으로 풀이되더라도 그 인연이나 기회를 어떻게 이어가는지가 더 중요하다고 여겨지기도 한다.'
  where not exists (select 1 from public.dreams where keyword = '반지꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[4,12,18,25,31,39] from new_dream_14;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '반지꿈'), '반지를-받는-꿈', '반지를 받는 꿈', '누군가에게서 정성스럽게 포장된 반지를 선물로 건네받는 꿈이다. 손가락에 끼워질 반지를 받는 장면은 전통적으로 새로운 인연이 맺어지거나 약속이 성사되는 신호로 해석되곤 한다. 반지를 준 사람이 가까운 사람이었다면 그 관계가 한층 깊어지고 신뢰가 두터워지는 조짐으로 풀이되는 경우가 많고, 얼굴을 알아볼 수 없는 낯선 이가 건넸다면 예상치 못한 곳에서 좋은 제안이나 기회가 찾아올 조짐으로 여겨지기도 한다. 반지를 받고 기뻐하며 손에 끼워보는 꿈이었다면 그 인연이나 약속을 마음으로도 받아들이고 있다는 뜻으로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 주변 사람들과의 약속이나 계약을 다시 한번 챙겨보는 계기로 삼는 경우도 있다.', '새로운 인연이나 약속이 맺어지는 신호', array[5,13,21,29,36,42], 1),
  ((select id from public.dreams where keyword = '반지꿈'), '반지를-잃어버리는-꿈', '반지를 잃어버리는 꿈', '손을 씻거나 옷을 갈아입다가 어느새 반지가 사라진 것을 알고 허둥대는 꿈이다. 소중히 지니던 반지를 잃어버리는 상황은 전통적으로 관계나 약속에 대한 불안한 마음, 혹은 자신감이 흔들리는 상태를 나타내는 신호로 해석되곤 한다. 반지를 찾으려고 온 집안을 뒤졌지만 결국 찾지 못했다면 마음속 걱정거리를 당분간 안고 가야 하는 시기로 풀이되는 경우가 많고, 우여곡절 끝에 반지를 다시 찾아냈다면 흔들렸던 관계나 마음이 곧 제자리를 찾을 조짐으로 여겨지기도 한다. 꿈에서 느낀 상실감이 유독 컸다면 현실에서도 소중한 관계를 조금 더 세심히 돌보고 있는 상태를 반영한다고 이야기되곤 한다. 이런 꿈을 꾼 뒤에는 가까운 사람과의 대화를 늘려보는 것이 도움이 된다고 전해진다.', '관계나 자신감이 흔들리는 불안한 조짐', null, 2),
  ((select id from public.dreams where keyword = '반지꿈'), '반지가-부러지는-꿈', '반지가 부러지는 꿈', '손가락에 끼고 있던 반지가 갑자기 툭 부러지거나 갈라지는 것을 목격하는 꿈이다. 단단해야 할 반지가 형태를 잃는 장면은 전통적으로 이어져 있던 관계나 계획에 예상치 못한 균열이 생길 수 있음을 암시하는 신호로 해석되곤 한다. 부러진 반지 조각을 주워 다시 이어 붙이려 했다면 틀어진 상황을 회복하려는 노력이 필요한 시기로 풀이되는 경우가 많고, 부러진 채로 그냥 두었다면 이미 정리가 필요한 인연이나 계획을 마음속으로 받아들이고 있는 상태로 보기도 한다. 반지가 부러지면서도 크게 놀라지 않았던 꿈이라면 변화를 담담하게 받아들일 준비가 되어 있다는 뜻으로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 중요한 약속이나 계약 조건을 다시 한번 확인해보는 것이 좋다고 이야기되곤 한다.', '이어진 관계나 계획에 균열이 생길 조짐', null, 3),
  ((select id from public.dreams where keyword = '반지꿈'), '반지를-끼는-꿈', '반지를 끼는 꿈', '거울 앞에서 반지를 골라 손가락에 천천히 끼워보는 꿈이다. 자신의 손에 맞는 반지를 끼우는 장면은 전통적으로 새로운 역할이나 책임을 받아들이려는 마음가짐, 혹은 관계의 결속을 다지는 상징으로 해석되곤 한다. 반지가 손가락에 꼭 맞아 편안했다면 지금 맺고 있는 인연이나 맡은 역할이 자신과 잘 어울린다는 조짐으로 풀이되는 경우가 많고, 반지가 헐겁거나 꽉 끼어 불편했다면 아직 서로 맞춰가는 시간이 더 필요한 상황으로 여겨지기도 한다. 여러 개의 반지를 번갈아 끼워보는 꿈이었다면 여러 선택지를 두고 고민하는 마음이 반영된 것으로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 지금의 결정이나 다짐을 한 번 더 되새겨보는 계기로 삼는 경우가 많다고 전해진다.', '새로운 역할이나 관계의 결속을 다지는 뜻', array[4,12,20,27,34,41], 4),
  ((select id from public.dreams where keyword = '반지꿈'), '금반지를-줍는-꿈', '금반지를 줍는 꿈', '길을 걷다가 반짝이는 금반지 하나가 바닥에 떨어져 있는 것을 발견하고 집어 드는 꿈이다. 값진 금반지를 뜻하지 않게 손에 넣는 장면은 전통적으로 예상치 못한 재물운이나 귀한 인연이 찾아드는 신호로 해석되곤 한다. 주운 금반지가 유난히 크고 화려했다면 그만큼 큰 행운이나 성과가 따라붙을 조짐으로 풀이되는 경우가 많고, 작고 소박한 금반지였다면 소소하지만 꾸준한 복이 이어질 조짐으로 여겨지기도 한다. 주인을 찾아주지 못한 채 금반지를 품에 넣는 꿈이었다면 뜻밖의 이득이 온전히 자신에게 머무를 조짐으로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 평소 지나쳤던 기회나 제안을 다시 살펴보는 계기로 삼는 경우도 있다.', '귀한 인연이나 재물운이 찾아드는 신호', array[6,15,23,30,37,45], 5)
on conflict (dream_id, keyword) do nothing;

-- C-15. 기차꿈 (신규 Parent, category: 교통)
with new_dream_15 as (
  insert into public.dreams (keyword, category, interpretation)
  select '기차꿈', '교통', '## 기차꿈은 보통 어떻게 해석할까?
기차는 정해진 선로를 따라 나아가는 교통수단으로, 꿈속에서는 계획한 일이 흘러가는 방향이나 속도, 그리고 그 과정에서 만나는 변수를 상징하는 경우가 많다. 기차를 타거나 내리는 꿈은 계획의 진행과 마무리를, 기차를 놓치거나 멈추는 꿈은 예상치 못한 지체나 기회의 상실을 나타내는 신호로 해석되곤 한다.

## 흐름의 순조로움이 만드는 해석 차이
기차꿈은 그 기차가 얼마나 순조롭게 달리는지에 따라 해석이 갈리는 편이다. 무사히 타고 목적지에 도착하는 꿈일수록 계획이 뜻대로 흘러가는 조짐으로, 놓치거나 멈추는 꿈일수록 준비와 점검이 필요한 시기로 풀이되는 경우가 많다고 전해진다.

## 기차꿈을 대할 때 참고할 점
기차꿈은 목적지보다 그 과정에서 느낀 감정이 해석의 실마리가 되는 경우가 많다고 이야기되곤 한다. 낯선 역이나 예상치 못한 정차라도 그 상황을 어떻게 받아들였는지에 따라 다가올 변화를 대하는 마음가짐을 가늠해볼 수 있다.'
  where not exists (select 1 from public.dreams where keyword = '기차꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[1,8,16,23,30,45] from new_dream_15;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '기차꿈'), '기차를-타는-꿈', '기차를 타는 꿈', '정해진 시간에 맞춰 플랫폼으로 나가 무사히 기차에 올라타는 꿈이다. 정해진 길을 따라 나아가는 기차에 몸을 싣는 장면은 전통적으로 계획한 일이 일정한 흐름을 타고 순조롭게 진행되는 조짐으로 해석되곤 한다. 창가 자리에 앉아 편안하게 풍경을 바라보았다면 지금 나아가는 방향에 대한 확신이 커지는 시기로 풀이되는 경우가 많고, 자리를 찾지 못해 서서 갔다면 계획은 진행되고 있지만 아직 안정된 위치를 잡지 못한 상태로 여겨지기도 한다. 함께 탄 사람이 있었다면 그 사람과 같은 방향의 목표를 향해 나아가고 있다는 뜻으로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 세워둔 계획의 다음 단계를 차근차근 점검해보는 계기로 삼는 경우가 많다.', '계획한 일이 순조롭게 진행되는 조짐', array[1,10,18,25,32,39], 1),
  ((select id from public.dreams where keyword = '기차꿈'), '기차를-놓치는-꿈', '기차를 놓치는 꿈', '서둘러 역에 도착했지만 눈앞에서 기차가 떠나버려 발을 동동 구르는 꿈이다. 정해진 시간을 맞추지 못하고 기차를 놓치는 상황은 전통적으로 좋은 기회를 눈앞에서 놓치거나 계획에 차질이 생길 수 있음을 알리는 신호로 해석되곤 한다. 다음 기차를 기다리며 마음을 다잡았다면 아쉬움은 있어도 곧 다른 기회로 이어질 조짐으로 풀이되는 경우가 많고, 대안조차 찾지 못한 채 발만 굴렀다면 상황을 다시 점검하고 계획을 손볼 필요가 있다는 뜻으로 여겨지기도 한다. 꿈에서 느낀 조급함이 유독 컸다면 현실에서도 시간에 쫓기며 무언가를 준비하고 있는 상태를 반영한다고 이야기되곤 한다. 이런 꿈을 꾼 뒤에는 중요한 일정을 여유 있게 다시 짜보는 것이 도움이 된다고 전해진다.', '좋은 기회를 놓치거나 계획에 차질 생길 신호', null, 2),
  ((select id from public.dreams where keyword = '기차꿈'), '기차가-멈추는-꿈', '기차가 멈추는 꿈', '잘 달리던 기차가 선로 한가운데서 갑자기 멈춰 서서 오도 가도 못하게 되는 꿈이다. 순조롭게 나아가던 기차가 뜻하지 않게 정지하는 상황은 전통적으로 진행 중이던 일이 잠시 지체되거나 예상치 못한 변수를 만나는 조짐으로 해석되곤 한다. 안내 방송을 듣고 이유를 알게 되었다면 문제의 원인을 파악해 곧 해결될 조짐으로 풀이되는 경우가 많고, 이유도 모른 채 마냥 기다려야 했다면 조금 더 인내심을 갖고 상황을 지켜봐야 하는 시기로 여겨지기도 한다. 기차가 멈춘 사이 다른 승객들과 이야기를 나누는 꿈이었다면 지체된 상황 속에서도 새로운 도움이나 정보를 얻게 될 조짐으로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 진행 중인 일의 대안을 미리 마련해두는 계기로 삼는 경우가 많다.', '진행 중인 일이 잠시 지체되는 조짐', null, 3),
  ((select id from public.dreams where keyword = '기차꿈'), '기차에서-내리는-꿈', '기차에서 내리는 꿈', '목적지에 다다라 짐을 챙기고 차분히 기차에서 내려서는 꿈이다. 달리던 기차에서 두 발로 내려서는 장면은 전통적으로 하나의 과정이 마무리되고 새로운 국면으로 들어서는 신호로 해석되곤 한다. 낯익은 역에 내렸다면 익숙한 환경에서 새로운 시작을 준비하게 되는 조짐으로 풀이되는 경우가 많고, 처음 보는 역에 내렸다면 낯선 환경이나 새로운 사람들과의 관계가 시작될 조짐으로 여겨지기도 한다. 내리자마자 홀가분한 기분이 들었다면 그동안 짊어지고 있던 부담을 내려놓게 되는 뜻으로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 마무리 짓지 못한 일을 정리하고 다음 단계를 준비해보는 계기로 삼는 경우가 많다.', '하나의 과정이 마무리되고 새로 시작되는 신호', array[8,16,24,31,38,44], 4),
  ((select id from public.dreams where keyword = '기차꿈'), '낯선-기차역에-도착하는-꿈', '낯선 기차역에 도착하는 꿈', '눈을 떠보니 한 번도 가본 적 없는 낯선 기차역 플랫폼에 서 있는 꿈이다. 익숙하지 않은 장소에 도착해 두리번거리는 상황은 전통적으로 예상하지 못했던 새로운 환경이나 기회가 눈앞에 펼쳐지는 조짐으로 해석되곤 한다. 역 주변이 밝고 활기차 보였다면 앞으로 다가올 변화가 긍정적인 방향으로 흘러갈 조짐으로 풀이되는 경우가 많고, 인적이 드물고 조용한 역이었다면 혼자서 차분히 새로운 길을 모색해야 하는 시기로 여겨지기도 한다. 역 이름이나 표지판을 유심히 살펴보는 꿈이었다면 새로운 상황을 신중하게 파악하려는 마음가짐이 반영된 것으로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 낯선 제안이나 기회를 열린 마음으로 검토해보는 계기로 삼는 경우가 많다.', '예상 못한 새로운 환경이나 기회가 열리는 조짐', array[3,11,19,27,35,43], 5)
on conflict (dream_id, keyword) do nothing;

-- C-16. 배꿈 (신규 Parent, category: 교통)
with new_dream_16 as (
  insert into public.dreams (keyword, category, interpretation)
  select '배꿈', '교통', '## 배꿈은 보통 어떻게 해석할까?
배는 물 위를 오가며 사람과 짐을 실어 나르는 교통수단으로, 꿈속에서는 인생의 항해나 진행 중인 일의 흐름을 상징하는 경우가 많다. 배를 타거나 큰 배를 보는 꿈은 새로운 출발이나 큰 기회가 다가오는 신호로, 배가 흔들리거나 침몰하는 꿈은 그 과정에서 만나는 위기나 변수를 나타내는 조짐으로 해석되곤 한다.

## 물살의 잔잔함과 거셈이 만드는 차이
배꿈은 바다나 물살의 상태에 따라 해석의 결이 크게 달라진다고 전해진다. 잔잔한 물 위를 순조롭게 나아가는 배는 안정적인 흐름을, 거센 물결에 흔들리거나 가라앉는 배는 대비와 점검이 필요한 시기를 나타내는 것으로 풀이되는 경우가 많다.

## 배꿈을 대할 때 참고할 점
배꿈은 위기 상황이라도 그것을 어떻게 헤쳐 나갔는지가 해석의 중요한 실마리가 된다고 이야기되곤 한다. 침착하게 대응하거나 무사히 벗어나는 꿈이었다면 어려움 속에서도 회복할 힘이 있다는 뜻으로 여겨지기도 한다.'
  where not exists (select 1 from public.dreams where keyword = '배꿈')
  returning id
)
insert into public.dream_number_mappings (dream_id, numbers)
select id, array[6,15,20,29,36,43] from new_dream_16;

insert into public.dream_situations (dream_id, keyword, title, body, key_meaning, numbers, display_order)
values
  ((select id from public.dreams where keyword = '배꿈'), '배를-타는-꿈', '배를 타는 꿈', '잔잔한 물 위에 떠 있는 배에 올라타 서서히 항해를 시작하는 꿈이다. 물살을 가르며 나아가는 배에 몸을 싣는 장면은 전통적으로 새로운 일이나 계획이 본격적으로 출발하는 신호로 해석되곤 한다. 바다가 맑고 잔잔했다면 그 계획이 큰 어려움 없이 순탄하게 흘러갈 조짐으로 풀이되는 경우가 많고, 물결이 약간 일렁였다면 크고 작은 변수를 겪으면서도 앞으로 나아가는 과정으로 여겨지기도 한다. 배 위에서 먼 곳을 바라보며 기대에 찬 마음이 들었다면 새로운 도전에 대한 설렘이 반영된 것으로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 세워둔 계획을 실제로 실행에 옮겨보는 계기로 삼는 경우가 많다.', '새로운 일이나 계획이 본격 출발하는 신호', array[2,9,17,25,33,40], 1),
  ((select id from public.dreams where keyword = '배꿈'), '배가-흔들리는-꿈', '배가 흔들리는 꿈', '항해 중이던 배가 거센 물결에 이리저리 흔들려 중심을 잡기 어려운 꿈이다. 안정적이어야 할 배가 크게 요동치는 상황은 전통적으로 진행 중인 일에 크고 작은 변수나 불안 요소가 끼어드는 조짐으로 해석되곤 한다. 흔들림 속에서도 난간을 붙잡고 버텨냈다면 어려움이 있어도 결국 균형을 되찾게 되는 흐름으로 풀이되는 경우가 많고, 몸을 가누지 못하고 휘청거렸다면 당분간 마음의 중심을 잡는 데 신경 써야 하는 시기로 여겨지기도 한다. 함께 탄 사람들과 서로 붙잡아주며 버틴 꿈이었다면 주변의 도움으로 위기를 넘길 조짐으로 풀이되기도 한다. 이런 꿈을 꾼 뒤에는 중요한 결정을 서두르지 않고 신중하게 살펴보는 것이 도움이 된다고 전해진다.', '진행 중인 일에 불안 요소가 끼어드는 조짐', null, 2),
  ((select id from public.dreams where keyword = '배꿈'), '배가-침몰하는-꿈', '배가 침몰하는 꿈', '타고 있던 배에 서서히 물이 차오르더니 결국 가라앉기 시작하는 꿈이다. 굳건하던 배가 물속으로 잠겨 드는 상황은 전통적으로 진행하던 일이 큰 위기를 맞거나 지금까지의 방식을 크게 바꿔야 할 수 있음을 암시하는 신호로 해석되곤 한다. 침몰하는 배에서 무사히 빠져나와 구조되는 꿈이었다면 위기를 넘기고 새로운 국면을 맞이하게 되는 조짐으로 풀이되는 경우가 많고, 빠져나오지 못한 채 물속에 잠기는 느낌으로 꿈이 끝났다면 지금의 방식을 근본적으로 다시 점검해야 하는 시기로 여겨지기도 한다. 침몰 속에서도 침착하게 구명조끼를 챙기는 꿈이었다면 위기 앞에서도 대비하는 태도가 반영된 것으로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 진행 중인 일의 위험 요소를 미리 점검해보는 계기로 삼는 경우가 많다.', '큰 위기로 방식을 근본적으로 바꿔야 할 신호', null, 3),
  ((select id from public.dreams where keyword = '배꿈'), '배에서-내리는-꿈', '배에서 내리는 꿈', '오랜 항해 끝에 목적지 항구에 닿아 배에서 육지로 내려서는 꿈이다. 흔들리던 배에서 벗어나 단단한 땅을 밟는 장면은 전통적으로 불안정했던 과정이 끝나고 안정된 상태로 접어드는 신호로 해석되곤 한다. 항구가 활기차고 사람들로 북적였다면 새로운 환경에서 좋은 기회를 만나게 될 조짐으로 풀이되는 경우가 많고, 조용하고 한적한 항구였다면 여유를 가지고 다음 단계를 준비하게 되는 시기로 여겨지기도 한다. 내리자마자 뒤를 돌아 배를 바라보는 꿈이었다면 지나온 과정을 돌아보며 마음을 정리하려는 태도로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 그동안의 노력을 되짚어보고 다음 목표를 세워보는 계기로 삼는 경우가 많다.', '불안정한 과정이 끝나고 안정에 접어드는 신호', array[5,13,21,28,36,44], 4),
  ((select id from public.dreams where keyword = '배꿈'), '큰-배를-보는-꿈', '큰 배를 보는 꿈', '멀리서 웅장한 크기의 배가 서서히 다가오는 모습을 지켜보는 꿈이다. 크고 위엄 있는 배가 눈앞에 나타나는 장면은 전통적으로 큰 규모의 기회나 뜻깊은 변화가 다가오는 조짐으로 해석되곤 한다. 그 배가 항구에 무사히 닻을 내렸다면 기다려온 성과나 좋은 소식이 가까이 다가왔다는 뜻으로 풀이되는 경우가 많고, 배가 먼바다에 계속 떠 있었다면 좋은 기회가 아직은 준비 과정에 있다는 뜻으로 여겨지기도 한다. 배에 실린 짐이나 사람들이 많아 보였다면 그만큼 풍성한 결실이나 도움이 함께 따라올 조짐으로 풀이되기도 한다. 이 꿈을 꾼 뒤에는 큰 계획을 세우고 실행할 준비를 갖추는 계기로 삼는 경우가 많다.', '큰 규모의 기회나 뜻깊은 변화가 다가오는 조짐', array[7,14,22,30,37,45], 5)
on conflict (dream_id, keyword) do nothing;

